157|fn highlight_file(path: &Path, text: &str) -> Vec<Vec<DiffSpan>> {
158|    let set = syntaxes();
159|    let syntax = syntax_for(path, set);
160|    let mut highlighter = HighlightLines::new(syntax, theme());
161|    let fallback = fallback_rgb();
162|    let mut lines = Vec::new();
163|    for line in LinesWithEndings::from(text) {
164|        let ranges = highlighter
165|            .highlight_line(line, set)
166|            .unwrap_or_else(|_| vec![(syntect::highlighting::Style::default(), line)]);
167|        let mut spans = Vec::new();
168|        for (style, piece) in ranges {
169|            let piece = piece.trim_end_matches(['\n', '\r']);
170|            if piece.is_empty() {
171|                continue;
172|            }
173|            spans.push(DiffSpan {
174|                text: piece.to_owned(),
175|                rgb: [style.foreground.r, style.foreground.g, style.foreground.b],
176|                intra: Intra::None,
177|            });
178|        }
179|        if spans.is_empty() {
180|            spans.push(DiffSpan {
181|                text: String::new(),
182|                rgb: fallback,
183|                intra: Intra::None,
184|            });
185|        }
186|        lines.push(spans);
187|    }
188|    if text.is_empty() {
189|        lines.clear();
190|    }
191|    lines
192|}
