211|fn line_spans(highlighted: &[Vec<DiffSpan>], index: Option<usize>, text: &str) -> Vec<DiffSpan> {
212|    let trimmed = text.trim_end_matches(['\n', '\r']);
213|    index
214|        .and_then(|i| highlighted.get(i).cloned())
215|        .filter(|spans| spans.iter().map(|s| s.text.as_str()).collect::<String>() == trimmed)
216|        .unwrap_or_else(|| {
217|            vec![DiffSpan {
218|                text: trimmed.to_owned(),
219|                rgb: fallback_rgb(),
220|                intra: Intra::None,
221|            }]
222|        })
223|}
