225|fn overlay(spans: Vec<DiffSpan>, fragments: &[(bool, String)]) -> Vec<DiffSpan> {
226|    let joined: String = fragments.iter().map(|(_, t)| t.as_str()).collect();
227|    let original: String = spans.iter().map(|s| s.text.as_str()).collect();
228|    if joined != original {
229|        return spans;
230|    }
231|    let mut colors = Vec::with_capacity(original.len());
232|    for span in &spans {
233|        for _ in 0..span.text.len() {
234|            colors.push(span.rgb);
235|        }
236|    }
237|    let mut out = Vec::new();
238|    let mut offset = 0;
239|    for (changed, text) in fragments {
240|        if text.is_empty() {
241|            continue;
242|        }
243|        let rgb = colors.get(offset).copied().unwrap_or_else(fallback_rgb);
244|        out.push(DiffSpan {
245|            text: text.clone(),
246|            rgb,
247|            intra: if *changed { Intra::Change } else { Intra::None },
248|        });
249|        offset = offset.saturating_add(text.len());
250|    }
251|    if out.is_empty() { spans } else { out }
252|}
