269|fn build_with_revealed(
270|    path: &Path,
271|    left: &str,
272|    right: &str,
273|    staged: bool,
274|    context: usize,
275|    revealed: Vec<std::ops::Range<usize>>,
276|) -> DiffDocument {
277|    let old_hl = highlight_file(path, left);
278|    let new_hl = highlight_file(path, right);
279|    let diff = TextDiff::from_lines(left, right);
280|    let mut doc = DiffDocument {
281|        left_label: if staged { "HEAD" } else { "Index" }.into(),
282|        right_label: if staged { "Index" } else { "Working tree" }.into(),
283|        left_text: left.into(),
284|        right_text: right.into(),
285|        context,
286|        revealed,
287|        ..Default::default()
288|    };
289|    let mut old_end = 0;
290|    let mut new_end = 0;
291|    for group in diff.grouped_ops(context) {
292|        if let Some(first) = group.first() {
293|            emit_gap(
294|                &mut doc,
295|                &diff,
296|                old_end..first.old_range().start,
297|                new_end..first.new_range().start,
298|                &old_hl,
299|                &new_hl,
300|            );
301|        }
302|        for op in &group {
303|            if op.tag() != DiffTag::Equal {
304|                doc.hunks.push(review::Hunk {
305|                    old: op.old_range(),
306|                    new: op.new_range(),
307|                    unified_row: doc.unified.len(),
308|                    split_row: doc.split.len(),
309|                });
310|            }
311|            emit_op(
312|                &diff,
313|                op,
314|                &old_hl,
315|                &new_hl,
316|                &mut doc.unified,
317|                &mut doc.split,
318|            );
319|            old_end = op.old_range().end;
320|            new_end = op.new_range().end;
321|        }
322|    }
323|    if !doc.hunks.is_empty() {
324|        emit_gap(
325|            &mut doc,
326|            &diff,
327|            old_end..left.split_inclusive('\n').count(),
328|            new_end..right.split_inclusive('\n').count(),
329|            &old_hl,
330|            &new_hl,
331|        );
332|    }
333|    doc
334|}
335|
336|fn emit_gap(
337|    doc: &mut DiffDocument,
338|    diff: &TextDiff<'_, '_, str>,
339|    old: std::ops::Range<usize>,
340|    new: std::ops::Range<usize>,
341|    old_hl: &[Vec<DiffSpan>],
342|    new_hl: &[Vec<DiffSpan>],
343|) {
344|    if old.is_empty() {
345|        return;
346|    }
347|    if doc
348|        .revealed
349|        .iter()
350|        .any(|range| range.start <= old.start && range.end >= old.end)
351|    {
352|        let op = similar::DiffOp::Equal {
353|            old_index: old.start,
354|            new_index: new.start,
355|            len: old.len(),
356|        };
357|        emit_op(diff, &op, old_hl, new_hl, &mut doc.unified, &mut doc.split);
358|        return;
359|    }
360|    let line = DiffLine {
361|        kind: LineKind::Hunk,
362|        old_no: None,
363|        new_no: None,
364|        spans: vec![DiffSpan {
365|            text: format!("⋯ {} unchanged lines ⋯", old.len()),
366|            rgb: fallback_rgb(),
367|            intra: Intra::None,
368|        }],
369|    };
370|    doc.gaps.push(review::Gap {
371|        old,
372|        new,
373|        unified_row: doc.unified.len(),
374|        split_row: doc.split.len(),
375|    });
376|    doc.unified.push(line.clone());
377|    doc.split.push(SplitRow {
378|        left: Some(line.clone()),
379|        right: Some(line),
380|    });
381|}
382|
383|fn emit_op(
384|    diff: &TextDiff<'_, '_, str>,
385|    op: &similar::DiffOp,
386|    old_hl: &[Vec<DiffSpan>],
387|    new_hl: &[Vec<DiffSpan>],
388|    unified: &mut Vec<DiffLine>,
389|    split: &mut Vec<SplitRow>,
390|) {
391|    match op.tag() {
392|        DiffTag::Equal => {
393|            for change in diff.iter_changes(op) {
394|                let line = equal_line(change, old_hl);
395|                unified.push(line.clone());
396|                split.push(SplitRow {
397|                    left: Some(line.clone()),
398|                    right: Some(line),
399|                });
400|            }
401|        }
402|        DiffTag::Delete => {
403|            for change in diff.iter_inline_changes(op) {
404|                let line = change_line(change, LineKind::Delete, old_hl, true);
405|                unified.push(line.clone());
406|                split.push(SplitRow {
407|                    left: Some(line),
408|                    right: None,
409|                });
410|            }
411|        }
412|        DiffTag::Insert => {
413|            for change in diff.iter_inline_changes(op) {
414|                let line = change_line(change, LineKind::Insert, new_hl, false);
415|                unified.push(line.clone());
416|                split.push(SplitRow {
417|                    left: None,
418|                    right: Some(line),
419|                });
420|            }
421|        }
422|        DiffTag::Replace => {
423|            let mut deletes = Vec::new();
424|            let mut inserts = Vec::new();
425|            for change in diff.iter_inline_changes(op) {
426|                match change.tag() {
427|                    ChangeTag::Delete => {
428|                        deletes.push(change_line(change, LineKind::Delete, old_hl, true));
429|                    }
430|                    ChangeTag::Insert => {
431|                        inserts.push(change_line(change, LineKind::Insert, new_hl, false));
432|                    }
433|                    ChangeTag::Equal => {}
434|                }
435|            }
436|            for line in &deletes {
437|                unified.push(line.clone());
438|            }
439|            for line in &inserts {
440|                unified.push(line.clone());
441|            }
442|            let rows = deletes.len().max(inserts.len());
443|            for i in 0..rows {
444|                split.push(SplitRow {
445|                    left: deletes.get(i).cloned(),
446|                    right: inserts.get(i).cloned(),
447|                });
448|            }
449|        }
450|    }
451|}
452|
453|fn equal_line(change: similar::Change<&str>, old_hl: &[Vec<DiffSpan>]) -> DiffLine {
454|    let text = change.value();
455|    DiffLine {
456|        kind: LineKind::Equal,
457|        old_no: change
458|            .old_index()
459|            .map(|n| u32::try_from(n).unwrap_or(u32::MAX).saturating_add(1)),
460|        new_no: change
461|            .new_index()
462|            .map(|n| u32::try_from(n).unwrap_or(u32::MAX).saturating_add(1)),
463|        spans: line_spans(old_hl, change.old_index(), text),
464|    }
465|}
466|
467|fn change_line(
468|    change: similar::InlineChange<'_, str>,
469|    kind: LineKind,
470|    highlighted: &[Vec<DiffSpan>],
471|    old_side: bool,
472|) -> DiffLine {
473|    let fragments: Vec<(bool, String)> = change
474|        .iter_strings_lossy()
475|        .map(|(changed, text)| (changed, text.trim_end_matches(['\n', '\r']).to_string()))
476|        .collect();
477|    let joined: String = fragments.iter().map(|(_, t)| t.as_str()).collect();
478|    let index = if old_side {
479|        change.old_index()
480|    } else {
481|        change.new_index()
482|    };
483|    let spans = overlay(line_spans(highlighted, index, &joined), &fragments);
484|    DiffLine {
485|        kind,
486|        old_no: change
487|            .old_index()
488|            .map(|n| u32::try_from(n).unwrap_or(u32::MAX).saturating_add(1)),
489|        new_no: change
490|            .new_index()
491|            .map(|n| u32::try_from(n).unwrap_or(u32::MAX).saturating_add(1)),
492|        spans,
493|    }
494|}
