103|/// Map a Git row click to the concrete action `App` performs. Conflicts open
104|/// as files; a deleted row with no staged side is a no-op; otherwise the diff
105|/// viewer preference picks native vs Neovim (Neovim only when the daemon
106|/// advertises it).
107|pub fn git_click_action(
108|    deleted: bool,
109|    staged: Option<bool>,
110|    clicked: bool,
111|    review_mode: ReviewMode,
112|    neovim_review: bool,
113|) -> Option<FileAction> {
114|    if !clicked {
115|        return None;
116|    }
117|    let Some(staged) = staged else {
118|        return if deleted {
119|            None
120|        } else {
121|            Some(FileAction::Open)
122|        };
123|    };
124|    if review_mode != ReviewMode::Neovim || !neovim_review {
125|        return Some(if staged {
126|            FileAction::NativeStagedDiff
127|        } else {
128|            FileAction::NativeWorkingDiff
129|        });
130|    }
131|    Some(if staged {
132|        FileAction::StagedDiff
133|    } else {
134|        FileAction::WorkingDiff
135|    })
136|}
