462|            .or(compare.upstream.as_deref());
463|        if let Some(target) = target {
464|            ui.add(
465|                egui::Label::new(RichText::new(format!("→ {target}")).monospace().weak())
466|                    .truncate(),
467|            )
468|            .on_hover_text("Base ref for the branch comparison");
469|        }
470|        if compare.ahead > 0 {
471|            ui.label(
