474|            )
475|            .on_hover_text("Commits ahead of the base ref");
476|        }
477|        if compare.behind > 0 {
478|            ui.label(RichText::new(format!("↓{}", compare.behind)).weak())
479|                .on_hover_text("Commits behind the base ref");
