259|pub(crate) fn build_with_context(
260|    path: &Path,
261|    left: &str,
262|    right: &str,
263|    staged: bool,
264|    context: usize,
265|) -> DiffDocument {
266|    build_with_revealed(path, left, right, staged, context, Vec::new())
