741|pub(super) fn build_change_tree(
742|    entries: &[&terminator_git::Change],
743|    root: Option<&Path>,
744|) -> ChangeTree {
745|    fn insert(node: &mut ChangeTree, dirs: &[String], change: &terminator_git::Change) {
746|        node.count = node.count.saturating_add(1);
747|        match dirs.split_first() {
748|            None => {
749|                node.files.push(change.clone());
750|                node.labels.push(
751|                    change
752|                        .path
753|                        .file_name()
754|                        .map(|name| name.to_string_lossy().into_owned())
755|                        .unwrap_or_default(),
756|                );
757|            }
758|            Some((dir, rest)) => insert(node.dirs.entry(dir.clone()).or_default(), rest, change),
759|        }
760|    }
761|    let mut tree = ChangeTree::default();
762|    for change in entries {
763|        let relative = root
764|            .and_then(|root| change.path.strip_prefix(root).ok())
765|            .unwrap_or(&change.path);
766|        let components: Vec<String> = relative
767|            .components()
768|            .map(|part| part.as_os_str().to_string_lossy().into_owned())
769|            .collect();
770|        if !components.is_empty() {
771|            let parent = components.len().saturating_sub(1);
772|            if let Some(dirs) = components.get(..parent) {
773|                insert(&mut tree, dirs, change);
774|            }
775|        }
776|    }
777|    tree
