13|pub(super) fn jump(
14|    ui: &egui::Ui,
15|    doc: &diff::DiffDocument,
16|    split: bool,
17|    review: &mut diff::review::State,
18|    scroll: &[egui::scroll_area::ScrollAreaOutput<()>],
19|    sync: &mut f32,
20|) {
21|    if !review.jump {
22|        return;
23|    }
24|    review.jump = false;
25|    let Some(hunk) = review.selected.and_then(|index| doc.hunks.get(index)) else {
26|        return;
27|    };
28|    #[allow(clippy::cast_precision_loss)]
29|    let top = hunk.row(split) as f32 * diff_row_height(ui);
30|    for output in scroll {
31|        let mut state = output.state;
32|        state.offset.y = (top - diff_row_height(ui))
33|            .max(0.0)
34|            .min((output.content_size.y - output.inner_rect.height()).max(0.0));
35|        if split {
36|            *sync = state.offset.y;
37|        }
38|        state.store(ui.ctx(), output.id);
39|    }
40|    ui.ctx().request_repaint();
41|}
