43|pub(super) fn change_color(
44|    hunk: &diff::review::Hunk,
45|    colors: super::diff_paint::DiffColors,
46|) -> Color32 {
47|    if hunk.replacement() {
48|        colors.accent
49|    } else if hunk.old.is_empty() {
50|        colors.added
51|    } else {
52|        colors.deleted
53|    }
54|}
