56|/// Fill a smooth from/to band as a triangle strip, including zero-line sides.
57|pub(super) fn paint_connector(
58|    ui: &egui::Ui,
59|    left: egui::Rect,
60|    right: egui::Rect,
61|    clip: egui::Rect,
62|    color: Color32,
63|) {
64|    let mut mesh = egui::Mesh::default();
65|    let mut top = Vec::new();
66|    let mut bottom = Vec::new();
67|    for step in 0_u32..=12 {
68|        #[allow(clippy::cast_precision_loss)]
69|        let t = step as f32 / 12.0;
70|        let blend = t * t * (3.0 - 2.0 * t);
71|        let x = egui::lerp(left.right()..=right.left(), t);
72|        let a = egui::pos2(x, egui::lerp(left.top()..=right.top(), blend));
73|        let b = egui::pos2(x, egui::lerp(left.bottom()..=right.bottom(), blend));
74|        top.push(a);
75|        bottom.push(b);
76|        mesh.colored_vertex(a, super::diff_paint::tint(color, 36));
77|        mesh.colored_vertex(b, super::diff_paint::tint(color, 36));
78|        if step > 0 {
79|            let index = step.saturating_mul(2);
80|            mesh.add_triangle(index.saturating_sub(2), index.saturating_sub(1), index);
81|            mesh.add_triangle(index.saturating_sub(1), index.saturating_add(1), index);
82|        }
83|    }
84|    let painter = ui.painter().with_clip_rect(clip);
85|    painter.add(egui::Shape::mesh(mesh));
86|    let stroke = egui::Stroke::new(1.0, super::diff_paint::tint(color, 110));
87|    painter.add(egui::Shape::line(top, stroke));
88|    painter.add(egui::Shape::line(bottom, stroke));
89|}
