92|pub(super) fn paint(
93|    ui: &mut egui::Ui,
94|    doc: &diff::DiffDocument,
95|    split: bool,
96|    staged: bool,
97|    enabled: bool,
98|    review: &mut diff::review::State,
99|    scroll: &[egui::scroll_area::ScrollAreaOutput<()>],
100|    rail: egui::Rect,
101|    unified_gutter: egui::Rect,
102|    colors: super::diff_paint::DiffColors,
103|) -> Interaction {
104|    let mut result = Interaction::default();
105|    let Some(last) = scroll.last() else {
106|        return result;
107|    };
108|    let Some(first) = scroll.first() else {
109|        return result;
110|    };
111|    let row_h = diff_row_height(ui);
112|    let count = diff_row_count(doc, split).max(1);
113|    let pointer = ui.ctx().input(|input| input.pointer.hover_pos());
114|    for (index, gap) in doc.gaps.iter().enumerate() {
115|        for (side, output) in scroll.iter().enumerate() {
116|            #[allow(clippy::cast_precision_loss)]
117|            let y = output.inner_rect.top() + gap.row(split) as f32 * row_h - output.state.offset.y;
118|            let rect = egui::Rect::from_min_size(
119|                egui::pos2(output.inner_rect.left(), y),
120|                egui::vec2(output.inner_rect.width(), row_h),
121|            )
122|            .intersect(output.inner_rect);
123|            if !rect.is_positive() {
124|                continue;
125|            }
126|            let click = ui
127|                .interact(
128|                    rect,
129|                    ui.id().with(("diff-gap", index, side)),
130|                    egui::Sense::click(),
131|                )
132|                .on_hover_text(format!("Show {} unchanged lines", gap.old.len()))
133|                .on_hover_cursor(egui::CursorIcon::PointingHand);
134|            #[cfg(feature = "test-support")]
135|            diagnostics::record(ui.ctx(), &format!("diff-gap-{index}"), rect);
136|            if click.clicked() {
137|                result.gap = Some(index);
138|            }
139|        }
140|    }
141|    for (index, hunk) in doc.hunks.iter().enumerate() {
142|        let color = change_color(hunk, colors);
143|        #[allow(clippy::cast_precision_loss)]
144|        let fraction = hunk.row(split) as f32 / count as f32;
145|        let marker = egui::Rect::from_center_size(
146|            egui::pos2(
147|                rail.center().x,
148|                rail.top() + fraction * (rail.height() - 6.0) + 3.0,
149|            ),
150|            egui::vec2(rail.width(), 6.0),
151|        );
152|        let selected = review.selected == Some(index);
153|        ui.painter().rect_filled(marker, 1.0, color);
154|        let click = ui
155|            .interact(
156|                marker.expand(2.0),
157|                ui.id().with(("diff-marker", index)),
158|                egui::Sense::click(),
159|            )
160|            .on_hover_text(format!(
161|                "Change {} of {}",
162|                index.saturating_add(1),
163|                doc.hunks.len()
164|            ));
165|        if click.clicked() {
166|            review.select(index);
167|        }
168|        #[cfg(feature = "test-support")]
169|        diagnostics::record(ui.ctx(), &format!("diff-marker-{index}"), marker);
170|        #[allow(clippy::cast_precision_loss)]
171|        let row_top = hunk.row(split) as f32 * row_h;
172|        #[allow(clippy::cast_precision_loss)]
173|        let old_height = if split {
174|            hunk.old.len() as f32 * row_h
175|        } else {
176|            hunk.rows(false).len() as f32 * row_h
177|        };
178|        #[allow(clippy::cast_precision_loss)]
179|        let new_height = if split {
180|            hunk.new.len() as f32 * row_h
181|        } else {
182|            old_height
183|        };
184|        let left = egui::Rect::from_min_size(
185|            egui::pos2(
186|                first.inner_rect.left(),
187|                first.inner_rect.top() + row_top - first.state.offset.y,
188|            ),
189|            egui::vec2(first.inner_rect.width(), old_height.max(1.0)),
190|        );
191|        let right = egui::Rect::from_min_size(
192|            egui::pos2(
193|                last.inner_rect.left(),
194|                last.inner_rect.top() + row_top - last.state.offset.y,
195|            ),
196|            egui::vec2(last.inner_rect.width(), new_height.max(1.0)),
197|        );
198|        if !left.intersects(first.inner_rect) && !right.intersects(last.inner_rect) {
199|            continue;
200|        }
201|        if split {
202|            let gap_clip = egui::Rect::from_min_max(
203|                egui::pos2(first.inner_rect.right(), first.inner_rect.top()),
204|                egui::pos2(last.inner_rect.left(), last.inner_rect.bottom()),
205|            );
206|            paint_connector(ui, left, right, gap_clip, color);
207|        }
208|        for (side, (rect, output)) in [(left, first), (right, last)].iter().enumerate() {
209|            if !split && side == 0 {
210|                continue;
211|            }
212|            let clip = output.inner_rect;
213|            let visible = rect.intersect(clip);
214|            if !visible.is_positive() {
215|                continue;
216|            }
217|            if selected {
218|                ui.painter().with_clip_rect(clip).rect_stroke(
219|                    *rect,
220|                    0.0,
221|                    egui::Stroke::new(1.0, color),
222|                    egui::StrokeKind::Inside,
223|                );
224|            }
225|            // Observe clicks without covering the text's selection widget.
226|            if pointer.is_some_and(|pos| visible.contains(pos))
227|                && ui.input(|input| input.pointer.primary_clicked())
228|            {
229|                review.selected = Some(index);
230|                review.confirm_discard = None;
231|            }
232|        }
233|        let band = left.union(right);
234|        if !selected && !pointer.is_some_and(|pos| band.contains(pos)) {
235|            continue;
236|        }
237|        let width = if split {
238|            (right.left() - left.right()).max(48.0)
239|        } else {
240|            unified_gutter.width()
241|        };
242|        let x = if split {
243|            left.right()
244|        } else {
245|            unified_gutter.left()
246|        };
247|        let y = left.top().max(first.inner_rect.top()).min(
248|            (first.inner_rect.bottom() - appearance::TOOLBAR_BUTTON).max(first.inner_rect.top()),
249|        );
250|        let controls = egui::Rect::from_min_size(
251|            egui::pos2(x, y),
252|            egui::vec2(width, appearance::TOOLBAR_BUTTON),
253|        );
254|        ui.scope_builder(
255|            egui::UiBuilder::new()
256|                .id_salt(("diff-hunk-actions", index))
257|                .max_rect(controls)
258|                .layout(egui::Layout::left_to_right(egui::Align::Center)),
259|            |ui| {
260|                ui.set_clip_rect(controls.intersect(ui.clip_rect()));
261|                ui.spacing_mut().item_spacing.x = 3.0;
262|                ui.add_space(((width - 47.0) / 2.0).max(0.0));
263|                ui.add_enabled_ui(enabled, |ui| {
264|                    let kind = if staged { Kind::Unstage } else { Kind::Stage };
265|                    let action = appearance::sidebar_action(
266|                        ui,
267|                        if staged { "ArrowLeft" } else { "Plus" },
268|                        &format!("{} this hunk", kind.label()),
269|                    );
270|                    #[cfg(feature = "test-support")]
271|                    diagnostics::record(
272|                        ui.ctx(),
273|                        &format!("diff-hunk-action-{index}"),
274|                        action.rect,
275|                    );
276|                    if action.clicked() {
277|                        result.action = Some((index, kind));
278|                    }
279|                    if !staged {
280|                        let discard =
281|                            appearance::sidebar_action(ui, "Eraser", "Discard this hunk…");
282|                        #[cfg(feature = "test-support")]
283|                        diagnostics::record(
284|                            ui.ctx(),
285|                            &format!("diff-hunk-discard-{index}"),
286|                            discard.rect,
287|                        );
288|                        if discard.clicked() {
289|                            result.action = Some((index, Kind::Discard));
290|                        }
291|                    }
292|                });
293|            },
294|        );
295|    }
296|    result
297|}
