66|pub fn perform(root: &Path, op: Op) -> Result<Report> {
67|    match op {
68|        Op::Stage(path) => git_path(root, &["add", "--"], &path, "Staged"),
69|        Op::Unstage(path) => git_path(root, &["restore", "--staged", "--"], &path, "Unstaged"),
70|        Op::Discard { path, untracked } => {
71|            if untracked {
72|                let path = contained_file(root, &path)?;
73|                fs::remove_file(&path).with_context(|| format!("delete {}", path.display()))?;
74|                Ok(Report::Message(format!("Removed {}", path.display())))
75|            } else {
76|                // Restore the worktree from the index (the default source),
77|                // never from HEAD: partially staged files keep their staged
78|                // content, and newly staged files have no HEAD version.
79|                git_path(root, &["restore", "--worktree", "--"], &path, "Discarded")
80|            }
81|        }
82|        Op::Delete(path) => delete(root, &path),
83|        Op::Commit(message) => commit(root, &message),
84|        Op::Branches => Ok(Report::Branches(branches(root)?)),
85|        Op::Switch(name) => switch(root, &name),
86|        Op::Log => Ok(Report::Log(log(root)?)),
87|        Op::Compare { base } => Ok(Report::Compare(compare(root, base.as_deref())?)),
88|        Op::CreateFile(path) => {
89|            let path = new_path(root, &path)?;
90|            ensure!(!link_exists(&path), "{} already exists", path.display());
91|            fs::write(&path, "").with_context(|| format!("create {}", path.display()))?;
92|            Ok(Report::Message(format!("Created {}", path.display())))
93|        }
94|        Op::CreateDir(path) => {
95|            let path = new_path(root, &path)?;
96|            ensure!(!link_exists(&path), "{} already exists", path.display());
97|            fs::create_dir(&path).with_context(|| format!("create {}", path.display()))?;
98|            Ok(Report::Message(format!("Created {}", path.display())))
99|        }
100|        Op::Duplicate(path) => {
101|            let path = contained_file(root, &path)?;
102|            let dest = duplicate_destination(&path)?;
103|            if fs::symlink_metadata(&path).is_ok_and(|meta| meta.file_type().is_symlink()) {
104|                replicate_symlink(&path, &dest)?;
105|            } else {
106|                fs::copy(&path, &dest).with_context(|| format!("copy {}", path.display()))?;
107|            }
108|            Ok(Report::Message(format!("Copied to {}", dest.display())))
109|        }
110|        Op::Rename { from, to } => {
111|            let from = contained_file(root, &from)?;
112|            let to = new_path(root, &to)?;
113|            ensure!(!link_exists(&to), "{} already exists", to.display());
114|            fs::rename(&from, &to).with_context(|| format!("rename {}", from.display()))?;
115|            Ok(Report::Message(format!("Renamed to {}", to.display())))
116|        }
117|        Op::Reveal(path) => {
118|            let path = contained_join(root, &path, true)?;
119|            reveal(&path)?;
120|            Ok(Report::Message(format!("Revealed {}", path.display())))
121|        }
122|    }
