239|pub(super) fn u8_from_f32(value: f32) -> u8 {
240|    if !value.is_finite() || value <= 0.0 {
241|        return 0;
242|    }
243|    if value >= 255.0 {
244|        return 255;
245|    }
246|    let mut out = 0_u8;
247|    let mut cursor = 0.0_f32;
248|    while cursor + 1.0 <= value {
249|        cursor += 1.0;
250|        out = out.saturating_add(1);
251|    }
252|    out
