343|    let label_left = if reserved { 36.0 } else { 26.0 };
344|    let previous_height = ui.spacing().interact_size.y;
345|    ui.spacing_mut().interact_size.y = height;
346|    let response = ui.add_sized(
347|        [ui.available_width(), height],
348|        egui::Button::new("").frame(false),
349|    );
350|    ui.spacing_mut().interact_size.y = previous_height;
351|    // Keep geometry and interaction IDs stable while avoiding text layout and
352|    // image loading for rows outside the sidebar viewport.
353|    if !ui.is_rect_visible(response.rect) {
354|        response.widget_info(|| {
355|            egui::WidgetInfo::selected(egui::WidgetType::SelectableLabel, true, selected, label)
356|        });
