358|    }
359|    if response.hovered() || selected {
360|        ui.painter().rect_filled(
361|            response.rect,
362|            4,
363|            if selected {
364|                ui.visuals().selection.bg_fill
365|            } else {
366|                ui.visuals().widgets.hovered.bg_fill
367|            },
368|        );
369|    }
370|    let trailing_width = if trailing.is_empty() {
371|        4.0
372|    } else {
373|        ui.painter()
374|            .layout_no_wrap(trailing.into(), FontId::proportional(12.0), tint)
375|            .size()
376|            .x
377|            + 12.0
378|    };
379|    let right = response.rect.right() - trailing_width;
380|    let rect = egui::Rect::from_min_max(
381|        egui::pos2(response.rect.left() + label_left, response.rect.top()),
382|        egui::pos2(
383|            right.max(response.rect.left() + label_left),
384|            response.rect.bottom(),
