162|/// Working icons rotate slowly: one turn per `STATUS_SPIN_PERIOD`, sampled at
163|/// `STATUS_SPIN_INTERVAL`. The wake rate dominates the cost — each wake paints
164|/// the visible UI — while rotating the paint itself is a cheap transform, so
165|/// the slower cadence keeps CPU low however the icon moves. The phase comes
166|/// from the wall clock, so several icons stay in sync, and egui keeps the
167|/// soonest request, so they share one schedule of at most two wakes per
168|/// second, usually coalesced with the app's one-second heartbeat. A clipped
169|/// icon, a hidden sidebar, a minimized window, or an unfocused window
170|/// (`focused == Some(false)`) does not request another frame. Unknown focus
171|/// still schedules. Keyboard, pointer, and terminal updates are separate.
172|pub(super) const STATUS_SPIN_INTERVAL: Duration = Duration::from_millis(500);
173|/// One full turn takes two seconds, so consecutive 500 ms frames step 90°:
174|/// visibly rotating, not flashing.
175|const STATUS_SPIN_PERIOD: f64 = 2.0;
176|
177|/// `as f32` for finite normals. Subnormals flush to zero; magnitudes past f32 saturate.
178|fn f32_from_f64(value: f64) -> f32 {
179|    let bits = value.to_bits();
180|    let sign = (bits >> 63) & 1;
181|    let exp_bits = (bits >> 52) & 0x7ff;
182|    let mant = bits & 0x000f_ffff_ffff_ffff;
183|    let Ok(exp_u) = u16::try_from(exp_bits) else {
184|        return 0.0;
185|    };
186|    if exp_u == 0x7ff {
187|        if mant != 0 {
188|            return f32::NAN;
189|        }
190|        return if sign == 0 {
191|            f32::INFINITY
192|        } else {
193|            f32::NEG_INFINITY
194|        };
195|    }
196|    if exp_u == 0 {
197|        return if sign == 0 { 0.0 } else { -0.0 };
198|    }
199|    let Some(unbiased) = i32::from(exp_u).checked_sub(1023) else {
200|        return 0.0;
201|    };
202|    if unbiased > 127 {
203|        return if sign == 0 {
204|            f32::INFINITY
205|        } else {
206|            f32::NEG_INFINITY
207|        };
208|    }
209|    if unbiased < -126 {
210|        return if sign == 0 { 0.0 } else { -0.0 };
211|    }
212|    let mut mantissa = mant >> 29;
213|    let remainder = mant & ((1_u64 << 29) - 1);
214|    if remainder > (1_u64 << 28) || (remainder == (1_u64 << 28) && mantissa & 1 == 1) {
215|        mantissa = mantissa.saturating_add(1);
216|    }
217|    let mut exp32 = unbiased.saturating_add(127);
218|    if mantissa >= (1_u64 << 23) {
219|        mantissa = 0;
220|        exp32 = exp32.saturating_add(1);
221|    }
222|    if exp32 >= 255 {
223|        return if sign == 0 {
224|            f32::INFINITY
225|        } else {
226|            f32::NEG_INFINITY
227|        };
228|    }
229|    let Ok(exp32) = u32::try_from(exp32) else {
230|        return 0.0;
231|    };
232|    let Ok(mantissa) = u32::try_from(mantissa) else {
233|        return 0.0;
234|    };
235|    let sign = u32::try_from(sign).unwrap_or(0);
236|    f32::from_bits((sign << 31) | (exp32 << 23) | mantissa)
237|}
