255|/// Paint an icon, optionally rotating it to signal ongoing work.
256|pub fn paint_status_icon(ui: &egui::Ui, rect: egui::Rect, icon: &str, tint: Color32, spin: bool) {
257|    if spin && !ui.is_rect_visible(rect) {
258|        return;
259|    }
260|    let mut image = egui::Image::new(crate::icons::source(icon));
261|    // Language icons carry their own palette; tinting them would flatten it.
262|    if !crate::icons::is_language(icon) {
263|        image = image.tint(tint);
264|    }
265|    if spin {
266|        let (angle, animate) = ui.input(|input| {
267|            let viewport = input.viewport();
268|            let turns = (input.time % STATUS_SPIN_PERIOD) / STATUS_SPIN_PERIOD;
269|            let angle = f32_from_f64(turns) * std::f32::consts::TAU;
270|            let animate = viewport.focused != Some(false) && !viewport.minimized.unwrap_or(false);
271|            (angle, animate)
272|        });
273|        image = image.rotate(angle, egui::Vec2::splat(0.5));
274|        if animate {
275|            ui.ctx().request_repaint_after(STATUS_SPIN_INTERVAL);
276|        }
277|    }
278|    image.paint_at(ui, rect);
