404|            ui.visuals().weak_text_color(),
405|        )
406|    });
407|    const GAP: f32 = 1.0;
408|    let block = galley.size().y + sub.as_ref().map_or(0.0, |s| GAP + s.size().y);
409|    let top = response.rect.center().y - block * 0.5;
410|    let label_center = top + galley.size().y * 0.5;
