412|        paint_status_icon(
413|            ui,
414|            egui::Rect::from_center_size(
415|                egui::pos2(response.rect.left() + 9.0, label_center),
416|                egui::vec2(14.0, 14.0),
417|            ),
418|            brand,
419|            ICON_COLOR,
420|            false,
421|        );
422|    }
423|    let size = if brand.is_some() { 14.0 } else { 16.0 };
424|    let icon_rect = egui::Rect::from_center_size(
