426|            response.rect.left() + if reserved { 25.0 } else { 12.0 },
427|            label_center,
428|        ),
429|        egui::vec2(size, size),
430|    );
431|    paint_status_icon(ui, icon_rect, icon, icon_tint.unwrap_or(ICON_COLOR), spin);
