    /// Replace the current diff pane in place with a sibling file's diff,","replace":"/// Replace one 0-based line of `text`, preserving its original line ending.
/// Out-of-range lines leave the text untouched.
pub(super) fn replace_line(text: &str, line: usize, replacement: &str) -> String {
    text.split_inclusive('\n')
        .enumerate()
        .map(|(index, part)| {
            if index == line {
                let ending = if part.ends_with("\r\n") {
                    "\r\n"
                } else if part.ends_with('\n') {
                    "\n"
                } else {
                    ""
                };
                format!("{replacement}{ending}")
            } else {
                part.to_owned()
            }
        })
        .collect()
}

