{"path":"crates/app/src/workspace_ui/diff_edit.rs","content":"//! In-diff editing: the diff tab keeps its two comparison panes, but the
//! working-tree side becomes a syntax-highlighted text editor. Changed lines
//! keep their diff tint, so editing never leaves the diff window.
use super::super::*;
use std::sync::Arc;

fn tint(color: Color32) -> Color32 {
    Color32::from_rgba_unmultiplied(color.r(), color.g(), color.b(), 42)
}

/// Per-line background tints for the editor panes: green for additions,
/// red for deletions, accent for replacements.
pub(super) fn line_tints(
    document: &diff::DiffDocument,
    colors: super::diff_paint::DiffColors,
) -> (Vec<Option<Color32>>, Vec<Option<Color32>>) {
    let left_lines = document.left_text.split_inclusive('\n').count();
    let right_lines = document.right_text.split_inclusive('\n').count();
    let mut left = vec![None; left_lines.max(1)];
    let mut right = vec![None; right_lines.max(1)];
    for hunk in &document.hunks {
        let (old_tint, new_tint) = if hunk.replacement() {
            (tint(colors.accent), tint(colors.accent))
        } else if hunk.old.is_empty() {
            (None, Some(tint(colors.added)))
        } else if hunk.new.is_empty() {
            (Some(tint(colors.deleted)), None)
        } else {
            (Some(tint(colors.deleted)), Some(tint(colors.added)))
        };
        for index in hunk.old.clone() {
            if let Some(slot) = left.get_mut(index) {
                *slot = old_tint;
            }
        }
        for index in hunk.new.clone() {
            if let Some(slot) = right.get_mut(index) {
                *slot = new_tint;
            }
        }
    }
    (left, right)
}

/// Layout job whose text is exactly the buffer text (a TextEdit requirement),
/// colored from cached syntect spans with per-line diff tints.
pub(super) fn highlighted_job(
    text: &str,
    spans: &[Vec<diff::DiffSpan>],
    tints: &[Option<Color32>],
    font: egui::FontId,
    fallback: Color32,
    wrap_width: f32,
) -> egui::text::LayoutJob {
    let mut job = egui::text::LayoutJob::default();
    job.wrap.max_width = wrap_width;
    for (index, part) in text.split_inclusive('\n').enumerate() {
        let background = tints.get(index).copied().flatten().unwrap_or(Color32::TRANSPARENT);
        let content = part.trim_end_matches(['\n', '\r']);
        let ending = &part[content.len()..];
        let line_spans: &[diff::DiffSpan] = spans.get(index).map_or(&[], Vec::as_slice);
        let joined: String = line_spans.iter().map(|span| span.text.as_str()).collect();
        if joined == content && !line_spans.is_empty() {
            for span in line_spans {
                job.append(
                    &span.text,
                    0.0,
                    egui::TextFormat {
                        font_id: font.clone(),
                        color: Color32::from_rgb(span.rgb[0], span.rgb[1], span.rgb[2]),
                        background,
                        ..Default::default()
                    },
                );
            }
        } else if !content.is_empty() {
            job.append(
                content,
                0.0,
                egui::TextFormat {
                    font_id: font.clone(),
                    color: fallback,
                    background,
                    ..Default::default()
                },
            );
        }
        if !ending.is_empty() {
            job.append(
                ending,
                0.0,
                egui::TextFormat {
                    font_id: font.clone(),
                    color: fallback,
                    background,
                    ..Default::default()
                },
            );
        }
    }
    if text.is_empty() {
        job.append(
            "",
            0.0,
            egui::TextFormat {
                font_id: font,
                color: fallback,
                ..Default::default()
            },
        );
    }
    job
}

#[allow(clippy::too_many_arguments)]
pub(super) fn show(
    ui: &mut egui::Ui,
    edit: &mut diff::review::Edit,
    read_only: bool,
    key: &str,
    path: &std::path::Path,
    colors: super::diff_paint::DiffColors,
) {
    // Refresh the cached syntax spans only when the edited text changes.
    if edit.left_spans.is_none() {
        edit.left_spans = Some(Arc::new(diff::highlight_spans(
            path,
            &edit.document.left_text,
        )));
    }
    if edit
        .right_spans
        .as_ref()
        .is_none_or(|(cached, _)| cached != &edit.text)
    {
        let spans = Arc::new(diff::highlight_spans(path, &edit.text));
        edit.right_spans = Some((edit.text.clone(), spans));
    }
    let left_spans = edit.left_spans.clone().unwrap_or_default();
    let right_spans = edit
        .right_spans
        .as_ref()
        .map_or_else(|| Arc::new(Vec::new()), |(_, spans)| Arc::clone(spans));
    let (left_tints, right_tints) = line_tints(&edit.document, colors);
    let font = egui::TextStyle::Monospace.resolve(ui.style());
    let fallback = colors.text;
    let cursor_line = edit.cursor_line.take();
    ui.columns(2, |columns| {
        for (side, ui) in columns.iter_mut().enumerate() {
            ui.horizontal(|ui| {
                ui.strong(if side == 0 {
                    &edit.document.left_label
                } else {
                    &edit.document.right_label
                });
                ui.weak(if side == 0 || read_only {
                    "Read-only"
                } else {
                    "Editable · Save to write to disk"
                });
            });
            let id = egui::Id::new((key, "diff-edit-text", side));
            egui::ScrollArea::both()
                .id_salt((key, "diff-edit-scroll", side))
                .auto_shrink([false, false])
                .show(ui, |ui| {
                    let (spans, tints) = if side == 0 {
                        (&left_spans, &left_tints)
                    } else {
                        (&right_spans, &right_tints)
                    };
                    let mut layouter = |ui: &egui::Ui, text: &str, wrap_width: f32| {
                        ui.fonts(|fonts| {
                            fonts.layout_job(highlighted_job(
                                text, spans, tints, font.clone(), fallback, wrap_width,
                            ))
                        })
                    };
                    // A &str TextBuffer permits selection and copy but rejects edits.
                    let output = if side == 1 && !read_only {
                        let mut editor = egui::TextEdit::multiline(&mut edit.text)
                            .id(id)
                            .font(egui::TextStyle::Monospace)
                            .layouter(&mut layouter)
                            .desired_width(f32::INFINITY);
                        let output = editor.show(ui);
                        if let Some(line) = cursor_line {
                            let char_index = edit
                                .text
                                .split_inclusive('\n')
                                .take(line)
                                .map(|part| part.chars().count())
                                .sum::<usize>();
                            let mut state = output.state.clone();
                            state.set_ccursor_range(Some(egui::text::CCursorRange::one(
                                egui::text::CCursor::new(char_index),
                            )));
                            state.store(ui.ctx(), id);
                            output.response.request_focus();
                        }
                        output
                    } else {
                        let mut snapshot = if side == 0 {
                            edit.document.left_text.as_str()
                        } else {
                            edit.text.as_str()
                        };
                        egui::TextEdit::multiline(&mut snapshot)
                            .id(id)
                            .font(egui::TextStyle::Monospace)
                            .layouter(&mut layouter)
                            .desired_width(f32::INFINITY)
                            .show(ui)
                    };
                    #[cfg(feature = "test-support")]
                    diagnostics::record(
                        ui.ctx(),
                        if side == 0 {
                            "diff-edit-old"
                        } else {
                            "diff-edit-local"
                        },
                        output.response.rect,
                    );
                    let _ = output;
                });
        }
    });
}

impl App {
    pub(crate) fn block_unsaved_diff(&mut self, key: Option<&str>) -> bool {
        let dirty = self.diff_reviews.iter().any(|(id, state)| {
            key.is_none_or(|key| key == id)
                && (state.unsaved_edits() || state.saving_edits && state.busy)
        });
        if dirty {
            self.error = Some("Save or discard edits in the diff viewer before closing.".into());
        }
        dirty
    }
}
"}

