/// The unified diff is editable in place: every new/equal row hosts a live
/// single-line editor over the shared buffer, delete and gap rows stay
/// painted. No double-click, no mode.
pub(super) fn paint_unified_editor(
    ui: &mut egui::Ui,
    doc: &diff::DiffDocument,
    buffer: &mut diff::review::Edit,
    path: &std::path::Path,
    colors: super::diff_paint::DiffColors,
    key: &str,
) -> egui::scroll_area::ScrollAreaOutput<()> {
    use super::diff_paint::{
        DiffGutter, DiffMetrics, DiffPaint, diff_content_width, diff_doc_digits, diff_row_style,
        fill_diff_row, gutter_cols, paint_diff_gutter, paint_diff_line, row_colors, DiffGutterPaint,
    };
    let (spans, valid, tints) = ensure_cache(buffer, path, colors);
    let metrics = DiffMetrics::measure(ui, diff_doc_digits(doc, false));
    let rows = doc.unified.len();
    let content = diff_content_width(ui, doc, false, &metrics, key);
    let width = content.max(ui.available_width());
    let font = egui::TextStyle::Monospace.resolve(ui.style());
    let fallback = colors.text;
    let mut pending: Option<(usize, String)> = None;
    let output = egui::ScrollArea::both()
        .id_salt((key, "unified-editor"))
        .auto_shrink([false, false])
        .show_rows(ui, metrics.row_h, rows, |ui, range| {
            ui.set_min_width(width);
            for index in range {
                let Some(line) = doc.unified.get(index) else {
                    continue;
                };
                let row_colors = row_colors(doc, index, false, colors);
                if line.kind == diff::LineKind::Delete || line.kind == diff::LineKind::Hunk {
                    paint_diff_line(
                        ui,
                        DiffPaint {
                            width,
                            line,
                            gutter: DiffGutter::Unified,
                            colors: row_colors,
                            metrics: &metrics,
                        },
                    );
                    continue;
                }
                let Some(new_no) = line.new_no else {
                    continue;
                };
                let line_index = (new_no.saturating_sub(1)) as usize;
                let (bg, sign) = diff_row_style(line.kind, row_colors);
                let cols = gutter_cols(&metrics, DiffGutter::Unified);
                let (rect, _) =
                    ui.allocate_exact_size(egui::vec2(width, metrics.row_h), egui::Sense::hover());
                fill_diff_row(ui, rect, cols.code, bg);
                paint_diff_gutter(
                    ui,
                    DiffGutterPaint {
                        rect,
                        cols,
                        line,
                        sign,
                        colors: row_colors,
                        metrics: &metrics,
                    },
                );
                let code_rect = egui::Rect::from_min_max(
                    egui::pos2(rect.left() + cols.code, rect.top()),
                    rect.max,
                );
                let original: String = line.spans.iter().map(|span| span.text.as_str()).collect();
                let mut local = buffer
                    .text
                    .split_inclusive('\\n')
                    .nth(line_index)
                    .map(|part| part.trim_end_matches(['\\n', '\\r']).to_owned())
                    .unwrap_or_else(|| original.clone());
                let line_spans: Vec<diff::DiffSpan> =
                    spans.get(line_index).cloned().unwrap_or_default();
                let line_valid = valid.get(line_index).copied().unwrap_or(false);
                let line_tint = tints.get(line_index).copied().flatten();
                ui.scope_builder(egui::UiBuilder::new().max_rect(code_rect), |ui| {
                    let mut layouter =
                        |ui: &egui::Ui, text: &dyn egui::TextBuffer, wrap_width: f32| {
                            ui.ctx().fonts_mut(|fonts| {
                                fonts.layout_job(highlighted_job(
                                    text.as_str(),
                                    std::slice::from_ref(&line_spans),
                                    &[line_valid],
                                    &[line_tint],
                                    font.clone(),
                                    fallback,
                                    wrap_width,
                                ))
                            })
